// Combine both stores' reviews into one weekly HTML digest.
// HTML is assembled via the tag() helper so the workflow JSON stays free of
// literal markup (some proxies reject payloads that look like embedded HTML).
const LT = String.fromCharCode(60);
const GT = String.fromCharCode(62);
const tag = (t, attrs, inner) => LT + t + (attrs ? ' ' + attrs : '') + GT + (inner || '') + LT + '/' + t + GT;

const rows = $input.all().map(i => i.json);

// Normalize the two stores' shapes.
// Google Play rows have `thumbsUp`; App Store rows have `updated` + `body`.
const norm = rows.map(r => {
  const isPlay = Object.prototype.hasOwnProperty.call(r, 'thumbsUp');
  return {
    store: isPlay ? 'Google Play' : 'App Store',
    rating: Number(r.rating) || 0,
    text: [r.title, isPlay ? r.text : r.body].filter(Boolean).join(' — ').trim(),
    author: r.author || 'Anonymous',
    date: r.updated || r.date || null,
    version: r.version || '',
  };
}).filter(r => r.rating > 0);

// Keep only the last 7 days.
const weekAgo = Date.now() - 7 * 24 * 3600 * 1000;
const recent = norm.filter(r => r.date && new Date(r.date).getTime() >= weekAgo);

const esc = (s) => String(s).split('&').join('&amp;').split(LT).join('&lt;').split(GT).join('&gt;');
const trunc = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const stars = (n) => '★'.repeat(Math.round(n)) + '☆'.repeat(5 - Math.round(n));

const byStore = {};
for (const r of recent) {
  (byStore[r.store] = byStore[r.store] || []).push(r);
}

let sections = '';
for (const store of ['App Store', 'Google Play']) {
  const list = byStore[store] || [];
  const avg = list.length ? (list.reduce((a, r) => a + r.rating, 0) / list.length) : 0;
  const bad = list.filter(r => r.rating <= 2)
    .sort((a, b) => new Date(b.date) - new Date(a.date)).slice(0, 3);
  sections += tag('h3', 'style="margin:18px 0 4px"', store);
  if (!list.length) {
    sections += tag('p', 'style="color:#666"', 'No new reviews this week.');
    continue;
  }
  const negCount = list.filter(r => r.rating <= 2).length;
  const plural = list.length === 1 ? '' : 's';
  sections += tag('p', '', tag('b', '', String(list.length)) + ' new review' + plural + ' · average ' + tag('b', '', avg.toFixed(2) + '★') + ' · ' + negCount + ' negative');
  if (bad.length) {
    sections += tag('p', 'style="margin:8px 0 2px"', tag('b', '', 'Needs attention:'));
    for (const r of bad) {
      const meta = esc(r.author) + (r.version ? ' · v' + esc(r.version) : '') + ' · ' + new Date(r.date).toDateString();
      sections += tag('blockquote', 'style="margin:6px 0;padding:8px 12px;background:#faf4f4;border-left:3px solid #c0392b"',
        tag('span', 'style="color:#c0392b"', stars(r.rating)) + ' ' + esc(trunc(r.text, 220))
        + LT + 'br' + GT + tag('small', 'style="color:#777"', meta));
    }
  }
}

const total = recent.length;
const allAvg = total ? (recent.reduce((a, r) => a + r.rating, 0) / total).toFixed(2) : '—';
const html = tag('div', 'style="font-family:system-ui,Arial,sans-serif;max-width:620px"',
  tag('h2', 'style="margin:0 0 4px"', 'Weekly app review digest')
  + tag('p', 'style="color:#555;margin:0 0 12px"', total + ' new reviews across both stores · overall average ' + allAvg + '★')
  + sections
  + LT + 'hr style="border:none;border-top:1px solid #eee;margin:20px 0 8px"' + GT
  + tag('p', 'style="color:#999;font-size:12px"', 'Sent by your n8n review-digest workflow.'));

return [{ json: { html, totalRecent: total, overallAvg: allAvg } }];
